      let caught = false;
      try {
        throw error;
      } catch (e) {
        if (e instanceof EsiError) {
          caught = true;
          expect(e.statusCode).toBe(0);
        }
      }

      expect(caught).toBe(true);
    });

    it('should maintain EsiError helper methods', () => {
      const error = new EsiValidationError(
